#!/usr/bin/env bash
set -euo pipefail
cd -- "$(dirname -- "$0")"
mkdir -p build
if ! latexmk -xelatex -interaction=nonstopmode -halt-on-error \
  -outdir=build preview.tex > build/build.log 2>&1; then
  tail -60 build/build.log
  exit 1
fi
cp build/preview.pdf preview.pdf
# Remove only the rendered pages generated by this preview command, so a
# shorter revised deck cannot leave old pages in the contact sheet.
rm -f -- build/slide-*.png
pdftoppm -scale-to 1100 -png preview.pdf build/slide > /dev/null 2>&1
python3 - <<'PY'
from pathlib import Path
from PIL import Image, ImageDraw

pages = sorted(Path('build').glob('slide-*.png'))
columns = 2
tile_width, tile_height = 820, 480
canvas = Image.new('RGB', (columns * tile_width,
                          ((len(pages) + columns - 1) // columns) * tile_height),
                   '#ebe8e6')
for index, path in enumerate(pages):
    slide = Image.open(path).convert('RGB')
    slide.thumbnail((800, 450))
    left = (index % columns) * tile_width + 10
    top = (index // columns) * tile_height + 24
    canvas.paste(slide, (left, top))
    ImageDraw.Draw(canvas).text((left, top - 18),
                               f'Slide {index + 1}', fill='#68615e')
canvas.save('preview.png')
print('Built preview.pdf and preview.png.')
PY
